UPDATE public.site_content SET payload='[{"id":"maze","title":"단체미로 공략","category":"컨텐츠 공략","thumbnail":"assets/guides/maze/1.jpg","updatedAt":"2026-03-28","description":"주 1회 클리어 가능한 단체미로 진행을 위한 지도 공략입니다.","steps":[{"title":"1번 통로","text":"입구 기준 첫 번째 이동 루트로 기본 동선 파악에 중요한 구간입니다.","img":"assets/guides/maze/1.jpg"},{"title":"지름길 통로","text":"다음 통로 이동을 빠르게 이어주는 핵심 지름길 구간입니다.","img":"assets/guides/maze/2.jpg"},{"title":"2번 통로","text":"두 번째 주요 이동 경로로 다른 통로와 연결되는 중간 단계입니다.","img":"assets/guides/maze/3.jpg"},{"title":"3번 통로","text":"중앙에서 이어지는 이동 경로로 방향 혼동이 많은 구간입니다.","img":"assets/guides/maze/4.jpg"},{"title":"미로수렵지","text":"사냥 및 이동이 동시에 이루어지는 핵심 지역입니다.","img":"assets/guides/maze/5.jpg"},{"title":"4번 통로","text":"후반 이동 루트로 출구 방향과 연결되는 중요한 통로입니다.","img":"assets/guides/maze/6.jpg"},{"title":"미로마룡 위치","text":"최종 목표 위치로 보스 및 핵심 도착 지점입니다.","img":"assets/guides/maze/7.jpg"}]},{"id":"miro","title":"개인미로 클리어 공략 영상","category":"컨텐츠 공략","updatedAt":"2026-03-28","description":"개인미로 클리어 영상(w.케이크장인)","steps":[{"title":"개인미로 클리어 영상","text":"영상을 참고하시고, 따라하시면 개인미로를 쉽게 클리어 할 수 있습니다.","link":"https://youtu.be/I1qPVdBdrf8?si=101pp5Ft7jIbEc-R"}]},{"id":"sagok","title":"사곡왕릉 가는 방법","category":"던전","thumbnail":"assets/guides/sagok/main.png","updatedAt":"2026-03-28","description":"사곡왕릉 진입 경로를 한 장으로 정리한 이미지형 공략입니다.","steps":[{"title":"사곡왕릉 경로","text":"순서대로 이동하면 사곡왕릉에 도달할 수 있습니다.","img":"assets/guides/sagok/main.png"}]},{"id":"mabang","title":"마방진 - 매주 1회(월요일 00시 초기화)","category":"컨텐츠 공략","thumbnail":"assets/guides/mabang/mabang.png","updatedAt":"2026-03-28","description":"마방진 클리어를 위한 가이드 문서","steps":[{"title":"마방진 클리어를 위한 참고","text":"1번~40번 방까지 미션을 해결하고 40번 방에서 보상을 획득","img":"assets/guides/mabang/mabang.png"}]}]'::jsonb, updated_at=now() WHERE section='guides' AND payload='[]'::jsonb;
UPDATE public.site_content SET payload='{"jobs":[{"id":"common","name":"공통","skills":[{"name":"이형환위","desc":"지정한 위치로 이동"},{"name":"흡기공","desc":"체력을 모두 회복합니다."}]},{"id":"warrior","name":"전사","skills":[{"name":"탄강기","desc":"범위 공격 + 부격효과(공격무공 사용불가)"},{"name":"금강불괴","desc":"방어력, 마법방어력 증가, HP 증가"},{"name":"사염검술","desc":"공격강화"},{"name":"참파격","desc":"적에게 이동, 도주가 가능"},{"name":"반공","desc":"4초간 입는 데미지를 반사"},{"name":"백강사자후","desc":"4초간 상대방을 제압"}]},{"id":"taoist","name":"도사","skills":[{"name":"혼령소환술","desc":"혼령 소환, 빨독"},{"name":"음양오행진","desc":"범위 장판"},{"name":"신전이술","desc":"주변 아군 HP, MP회복 + 선천기공"},{"name":"암독운계","desc":"타겟 적군 중독 또는 마비"},{"name":"풍비","desc":"지정 위치로 이동 및 주변 아군 정화, 타겟 적군과 위치 교체"},{"name":"만효부","desc":"아군대상 범위 정화&선천, 적군대상 일정확률로 피해감소의 일정수치 무력화"}]},{"id":"sorcerer","name":"술사","skills":[{"name":"화마염폭","desc":"불꽃 장판"},{"name":"뢰선풍","desc":"주변마비 + 이동기"},{"name":"역혈마공","desc":"주변 범위 데미지 + 체력 흡수"},{"name":"낙뢰","desc":"지정 범위에  + 일정 확률 강화된 낙뢰"},{"name":"환영술","desc":"본인과 같은 무공을 쓰는 환영을 소환"},{"name":"흡마염풍","desc":"범위화마의 기운을 회오리 형태로 구현, 적군을 끌어당깁니다."}]},{"id":"assassin","name":"자객","skills":[{"name":"낭기식","desc":"주변 범위 마비"},{"name":"월영무","desc":"은신 상태 돌입"},{"name":"살풍","desc":"강력한 데미지 + HP흡수"},{"name":"교악","desc":"범위데미지, 방어무공 해제(확률)"},{"name":"무달경","desc":"타겟의 뒤로 순간이동"},{"name":"영화연격","desc":"일시적으로 피해를 받지 않고 타겟에게 순간이동하여 여러번 피격합니다. 일정확률로 보호무공(선천,주막,회풍 등)을 파괴합니다."}]},{"id":"archer","name":"궁사","skills":[{"name":"낭아섬","desc":"적군 MP 소모 + 마비"},{"name":"혈룡섬비급","desc":"주변 범위 데미지 + 빙결"},{"name":"몽안술","desc":"시야 차단"},{"name":"십이사격","desc":"타겟의 버프해제"},{"name":"옥쇄술","desc":"타겟의 발을 묶어 이동기 제한"},{"name":"낙뢰살","desc":"타겟 빛 주변 범위에 낙뢰를 발생시킵니다."}]},{"id":"magic","name":"원사","skills":[{"name":"천지검기","desc":"지정된 범위에 바람의 기운을 모아 검기를 떨어트립니다."},{"name":"용천우신조","desc":"HP, MP, 능력치 증가 및 특정 무공 강화"},{"name":"회풍강막","desc":"본인 또는 아군에게 일정시간 피해를 막아주는 방어막을 생성합니다."},{"name":"전고사려","desc":"넓은 범위 내 몬스터에게 강력한 불기둥을 만들어 피해를 주는 무공"},{"name":"사취","desc":"적의 무공을 일시적으로 빼앗아 사용할 수 있는 무공입니다."},{"name":"압수","desc":"회풍강막을 제거하고, 사취한 무공을 잃게 만듭니다. 몬스터에게는 범위로 강력한 피해를 줍니다."}]}]}'::jsonb, updated_at=now() WHERE section='skills' AND payload=' {"jobs":[]} '::jsonb;
